    for a,y in YOUNG: out.append((f"ماذا يُسمّى صغير {a}؟",o(y,[x for _,x in YOUNG])))
    for a,s in SOUND: out.append((f"ماذا يُسمّى صوت {a}؟",o(s,[x for _,x in SOUND])))
    for a,h in HOME: out.append((f"ماذا يُسمّى مسكن {a}؟",o(h,[x for _,x in HOME])))
    for q,a,d in FACTS: out.append((q,[a]+[x for x in d if x!=a][:3] if len({len(x.split()) for x in [a]+d[:3]})==1 else o(a,d)))
    return out
